function solve(a, b) {
  const table = [];
  for (let i = 0; i <= a.length; i++) table.push(new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      if (a[i - 1] === b[j - 1]) table[i][j] = table[i - 1][j - 1] + 1;
      else table[i][j] = Math.max(table[i - 1][j], table[i][j - 1]);
    }
  }
  return table[a.length][b.length];
}

function solve(a, b) {
  let wide = a;
  let narrow = b;
  if (narrow.length > wide.length) {
    const held = wide;
    wide = narrow;
    narrow = held;
  }
  let above = new Array(narrow.length + 1).fill(0);
  let current = new Array(narrow.length + 1).fill(0);
  for (let i = 1; i <= wide.length; i++) {
    const char = wide[i - 1];
    for (let j = 1; j <= narrow.length; j++) {
      if (char === narrow[j - 1]) current[j] = above[j - 1] + 1;
      else current[j] = Math.max(above[j], current[j - 1]);
    }
    const held = above;
    above = current;
    current = held;
  }
  return above[narrow.length];
}
